#!/usr/bin/env bash
# Run in the terminal to inspect a PNG generated by local.sh or linux.sh:
#   poc/scripts/preview.sh poc/output/<run>/fraction.png [--halfblocks]
# Requires Rust/Cargo and the same build prerequisites as local.sh. The terminal
# must be interactive. The default queries its graphics capabilities and falls
# back to half-blocks if the query fails; --halfblocks forces that fallback.
# The legacy viewer scales each dimension to one half, composites on white, then fits
# the image to the available area if necessary. It
# redraws on terminal events including resize. Space hides/shows it; q or Escape quits.
# It does not change the PNG. Record terminal/version and shown protocol when
# evaluating results. This viewer is an experiment, not the product layout.
set -euo pipefail
if (( $# < 1 || $# > 2 )) || { (( $# == 2 )) && [[ "$2" != --halfblocks ]]; }; then
    printf 'Usage: %s PNG [--halfblocks]\n' "$0" >&2
    exit 2
fi
script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
poc_dir="$(cd -- "$script_dir/.." && pwd -P)"
export CARGO_TARGET_DIR="$HOME/.cache/rateq-poc/$(uname -s)-$(uname -m)"
exec cargo run --locked --release --manifest-path "$poc_dir/Cargo.toml" -- preview "$@"
